"""
    retrieve container volumes details
    """
def get_volumes(container: Any) -> object {
    mounts = container.get('Mounts');
    return [
        `dict(source=mount['Source'], destination=mount['Destination'])
        for mount in mounts
    ];
}

"""Find and return seat numbers that are unassigned.

    :param seats: dict - seating chart.
    :return: list - list of seat numbers available for reserving..
    """
def find_all_available_seats(seats: Any) -> object {
    available = [];
    for (seat_num, value) in seats.items() {
        if (value is None) {
            available.append(seat_num);
        }
    }
    return available;
}

