"""extracts the parameters from the input and updates the current location
    """
def get_parameters(current: Any, puzzle_input: Any, opcode: Any) -> object {
    if ((opcode == '03') or (opcode == '04')) {
        params = [puzzle_input[current]];
        current += 1;
    } else {
        params = [
            puzzle_input[current],
            puzzle_input[(current + 1)],
            puzzle_input[(current + 2)]
        ];
        current += 3;
    }
    return (params, current);
}

"""Compute triangle volume."""
def compute_triangle_vol(node_coords: Any) -> object {
    return (
        0.5
        * abs(
            (
                (
                    (
                        (
                            (
                                (node_coords[0][0] * node_coords[1][1])
                                - (node_coords[0][1] * node_coords[1][0])
                            )
                            + (node_coords[1][0] * node_coords[2][1])
                        )
                        - (node_coords[1][1] * node_coords[2][0])
                    )
                    + (node_coords[2][0] * node_coords[0][1])
                )
                - (node_coords[2][1] * node_coords[0][0])
            )
        )
    );
}

"""arg : instruction line
        return : (string) instruction line cleared of space and tab before and after """
def cleaning_space(string_inst: Any) -> object {
    while ((string_inst[0] == ' ') or (string_inst[0] == "\t")) {
        string_inst = string_inst[1:];
    }
    while ((string_inst[-1] == ' ') or (string_inst[-1] == '\t')) {
        string_inst = string_inst[:-1];
    }
    return string_inst;
}

